nft.nat4:
ip
chain prerouting {
  type nat hook prerouting priority dstnat; policy accept;
  iifname "wan0" ip saddr { 198.51.100.0/24 } tcp dport { 443 } dnat to 10.71.0.10
}
chain postrouting {
  type nat hook postrouting priority srcnat; policy accept;
  # The announced WAN net sees every site as the WAN address
oifname "wan0" ip daddr 192.0.2.0/24 masquerade

  # Internet-bound only; our other networks (trusted.v4) are routed, not NATed.
  oifname "wan0" ip saddr 10.71.0.0/16 ip daddr != { 10.0.0.0/8 } masquerade
}

nft.nat6:
ip6
chain prerouting {
  type nat hook prerouting priority dstnat; policy accept;
  iifname "wan0" udp dport { 51821 } dnat to fd71:0:0:1::10
}
chain postrouting {
  type nat hook postrouting priority srcnat; policy accept;

  oifname "wan0" ip6 saddr fd71::/48 ip6 daddr != { fc00::/7, 2001:678:dc0::/48 } masquerade

}

radvd:
interface lan0 {
  AdvSendAdvert on;
  MinRtrAdvInterval 200;
  MaxRtrAdvInterval 300;
  AdvLinkMTU 1500;
  AdvCurHopLimit 64;
  AdvManagedFlag on;
  AdvOtherConfigFlag on;
  RemoveAdvOnExit on;
  prefix fd71:0:0:1::/64 {
    DeprecatePrefix on;
    AdvOnLink on;
    AdvAutonomous off;
  };
  RDNSS fd71:0:0:1::1 {
  };
  DNSSL spoke.example.org {
  };
};
